 mô tả nào đúng nhất về “Câu hỏi nghiên cứu”?","options":["Xác định thông tin cụ thể cần trả lời trong hồ sơ","Ghi tên tài liệu, đơn vị, ngày và liên kết","Dùng nhiều nguồn để xác minh kết luận quan trọng","Liên kết nhận định với nguồn chứng cứ tương ứng"],"correct":0},{"text":"Trong bài học, mô tả nào đúng nhất về “Bảng nguồn tham khảo”?","options":["Đánh giá thẩm quyền, thời điểm, bằng chứng và tính độc lập","Nêu rõ thông tin còn thiếu hoặc chưa được xác minh","Chỉ khẳng định trong phạm vi bằng chứng hiện có","Ghi tên tài liệu, đơn vị, ngày và liên kết"],"correct":3},{"text":"Trong bài học, mô tả nào đúng nhất về “Tiêu chí tin cậy”?","options":["Liên kết nhận định với nguồn chứng cứ tương ứng","Xác định thông tin cụ thể cần trả lời trong hồ sơ","Đánh giá thẩm quyền, thời điểm, bằng chứng và tính độc lập","Dùng nhiều nguồn để xác minh kết luận quan trọng"],"correct":2},{"text":"Trong bài học, mô tả nào đúng nhất về “Bằng chứng đối chiếu”?","options":["Ghi tên tài liệu, đơn vị, ngày và liên kết","Dùng nhiều nguồn để xác minh kết luận quan trọng","Nêu rõ thông tin còn thiếu hoặc chưa được xác minh","Chỉ khẳng định trong phạm vi bằng chứng hiện có"],"correct":1},{"text":"Trong bài học, mô tả nào đúng nhất về “Ghi giới hạn dữ liệu”?","options":["Nêu rõ thông tin còn thiếu hoặc chưa được xác minh","Liên kết nhận định với nguồn chứng cứ tương ứng","Xác định thông tin cụ thể cần trả lời trong hồ sơ","Đánh giá thẩm quyền, thời điểm, bằng chứng và tính độc lập"],"correct":0},{"text":"Trong bài học, mô tả nào đúng nhất về “Trích dẫn trong báo cáo”?","options":["Chỉ khẳng định trong phạm vi bằng chứng hiện có","Ghi tên tài liệu, đơn vị, ngày và liên kết","Dùng nhiều nguồn để xác minh kết luận quan trọng","Liên kết nhận định với nguồn chứng cứ tương ứng"],"correct":3},{"text":"Trong bài học, mô tả nào đúng nhất về “Kết luận có điều kiện”?","options":["Đánh giá thẩm quyền, thời điểm, bằng chứng và tính độc lập","Nêu rõ thông tin còn thiếu hoặc chưa được xác minh","Chỉ khẳng định trong phạm vi bằng chứng hiện có","Xác định thông tin cụ thể cần trả lời trong hồ sơ"],"correct":2},{"text":"Thuật ngữ nào phù hợp nhất với mô tả: “Xác định thông tin cụ thể cần trả lời trong hồ sơ”?","options":["Bảng nguồn tham khảo","Bằng chứng đối chiếu","Trích dẫn trong báo cáo","Câu hỏi nghiên cứu"],"correct":3},{"text":"Thuật ngữ nào phù hợp nhất với mô tả: “Ghi tên tài liệu, đơn vị, ngày và liên kết”?","options":["Ghi giới hạn dữ liệu","Kết luận có điều kiện","Bảng nguồn tham khảo","Tiêu chí tin cậy"],"correct":2},{"text":"Thuật ngữ nào phù hợp nhất với mô tả: “Đánh giá thẩm quyền, thời điểm, bằng chứng và tính độc lập”?","options":["Câu hỏi nghiên cứu","Tiêu chí tin cậy","Bằng chứng đối chiếu","Trích dẫn trong báo cáo"],"correct":1}]}]$bank$::jsonb) LOOP
   SELECT cc.course_id INTO STRICT v_course FROM lms.curated_courses cc WHERE cc.course_key=s->>'key';
   SELECT l.lesson_id INTO STRICT v_lesson FROM lms.lessons l WHERE l.course_id=v_course
      AND l.lesson_order=(s->>'order')::int AND l.is_published AND NOT l.is_deleted;
   SELECT q.quiz_id INTO v_quiz FROM assessment.quizzes q WHERE q.lesson_id=v_lesson
      AND q.course_id=v_course AND q.is_published AND NOT q.is_deleted ORDER BY q.quiz_id DESC LIMIT 1;
   IF v_quiz IS NULL THEN
     INSERT INTO assessment.quizzes(course_id,lesson_id,title,description,time_limit_seconds,passing_score,max_attempts,is_published)
     VALUES(v_course,v_lesson,'Quiz cuối bài','[VEDU-PATCH-POWERPOINT-DIGITAL-V1]',900,7,3,true)
     RETURNING quiz_id INTO v_quiz;
   END IF;
   SELECT COUNT(*) INTO v_count FROM assessment.questions WHERE quiz_id=v_quiz;
   IF v_count NOT IN (0,3,10) THEN RAISE EXCEPTION 'Unexpected quiz % question count %',v_quiz,v_count; END IF;
   SELECT COUNT(*) INTO v_attempts FROM assessment.quiz_attempts WHERE quiz_id=v_quiz;
   IF v_count=0 AND v_attempts>0 THEN RAISE EXCEPTION 'Quiz % has attempts but no questions',v_quiz; END IF;
   FOR i IN 1..(CASE WHEN v_count=0 THEN 10 ELSE 7 END) LOOP
      IF v_count=10 THEN EXIT; END IF;
      item:=s->'questions'->(i-1);
      IF jsonb_array_length(item->'options')<>4 THEN RAISE EXCEPTION 'Invalid answer choices'; END IF;
      INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
      VALUES(v_quiz,item->>'text','SINGLE_CHOICE',v_count+i,1) RETURNING question_id INTO v_q;
      FOR j IN 1..4 LOOP
         INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
         VALUES(v_q,item->'options'->>(j-1),((item->>'correct')::int=j-1),j);
      END LOOP;
   END LOOP;
   UPDATE assessment.quizzes SET time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900),updated_at=now() WHERE quiz_id=v_quiz;
   IF (SELECT COUNT(*) FROM assessment.questions WHERE quiz_id=v_quiz)<>10 THEN
      RAISE EXCEPTION 'Quiz % does not have 10 questions',v_quiz;
   END IF;
 END LOOP;
END $patch$;
COMMIT;
